mapper.select:
SELECT
    from_id, from_name, tenant_id, register_date, register_user
FROM SES_AI_M_SENDER
WHERE from_id = #{fromId}
  AND tenant_id = #{tenantId}

mapper.update:
UPDATE SES_AI_M_SENDER
SET
    from_name = #{fromName}
WHERE from_id = #{fromId}
  AND tenant_id = #{tenantId}

mapper.delete:
DELETE FROM SES_AI_M_SENDER
WHERE from_id = #{fromId}
  AND tenant_id = #{tenantId}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM SES_AI_M_SENDER
    WHERE from_id = #{fromId}
      AND tenant_id = #{tenantId}
)
